import curses
import time

def draw_board(stdscr, board):
    stdscr.clear()
    for i in range(3):
        for j in range(3):
            cell = board[i][j]
            if cell == 0:
                stdscr.addch(i*2+1, j*2+1, ' ')
            elif cell == 1:
                stdscr.addch(i*2+1, j*2+1, 'X')
            else:
                stdscr.addch(i*2+1, j*2+1, 'O')
    stdscr.refresh()

def get_input(stdscr, board):
    while True:
        key = stdscr.getch()
        if key == ord('q'):
            return None
        elif key == curses.KEY_UP:
            return (0, -1)
        elif key == curses.KEY_DOWN:
            return (0, 1)
        elif key == curses.KEY_LEFT:
            return (-1, 0)
        elif key == curses.KEY_RIGHT:
            return (1, 0)

def is_valid_move(board, move):
    x, y = move
    return 0 <= x < 3 and 0 <= y < 3 and board[x][y] == 0

def make_move(board, move, player):
    x, y = move
    board[x][y] = player

def check_winner(board):
    for i in range(3):
        if board[i][0] == board[i][1] == board[i][2] != 0:
            return board[i][0]
        if board[0][i] == board[1][i] == board[2][i] != 0:
            return board[0][i]
    if board[0][0] == board[1][1] == board[2][2] != 0:
        return board[0][0]
    if board[0][2] == board[1][1] == board[2][0] != 0:
        return board[0][2]
    return None

def main(stdscr):
    curses.curs_set(0)
    stdscr.timeout(100)
    stdscr.keypad(1)
    board = [[0 for _ in range(3)] for _ in range(3)]
    current_player = 1
    winner = None

    while winner is None:
        draw_board(stdscr, board)
        move = get_input(stdscr, board)
        if move is None:
            break
        if is_valid_move(board, move):
            make_move(board, move, current_player)
            winner = check_winner(board)
            current_player = 3 - current_player

    draw_board(stdscr, board)
    if winner is not None:
        stdscr.addstr(4, 0, f"Player {winner} wins!")
    else:
        stdscr.addstr(4, 0, "It's a draw!")
    stdscr.refresh()
    time.sleep(2)

if __name__ == "__main__":
    curses.wrapper(main)

