import curses
import sys

def get_secret_number():
    if len(sys.argv) > 1:
        try:
            return int(sys.argv[1])
        except ValueError:
            pass
    return None

def get_user_guess(stdscr):
    stdscr.addstr(1, 0, "Enter your guess: ")
    stdscr.refresh()
    guess = stdscr.getstr(1, 15, 10).decode('utf-8')
    return guess

def check_guess(guess, secret):
    try:
        guess = int(guess)
        if guess < secret:
            return 'lower'
        elif guess > secret:
            return 'higher'
        else:
            return 'won'
    except ValueError:
        return None

def main(stdscr):
    curses.curs_set(0)
    stdscr.timeout(100)
    stdscr.keypad(1)

    secret = get_secret_number()
    if secret is None:
        stdscr.addstr(0, 0, "Usage: python number_guessing_game.py <secret_number>")
        stdscr.refresh()
        stdscr.getch()
        return

    guess_count = 0
    while True:
        stdscr.clear()
        stdscr.addstr(0, 0, f"Guess {guess_count + 1}:")
        guess = get_user_guess(stdscr)
        if guess == 'q':
            break

        result = check_guess(guess, secret)
        if result == 'lower':
            stdscr.addstr(2, 0, "Too low!")
        elif result == 'higher':
            stdscr.addstr(2, 0, "Too high!")
        elif result == 'won':
            stdscr.addstr(2, 0, f"Won in {guess_count + 1} guesses!")
            break

        stdscr.refresh()
        guess_count += 1

if __name__ == "__main__":
    curses.wrapper(main)
