import argparse
import json
import os

def load_shopping_list(file_path):
    if os.path.exists(file_path):
        with open(file_path, 'r') as file:
            return json.load(file)
    return []

def save_shopping_list(file_path, shopping_list):
    with open(file_path, 'w') as file:
        json.dump(shopping_list, file, indent=4)

def add_item(shopping_list, item):
    if item not in shopping_list:
        shopping_list.append(item)

def check_item(shopping_list, item):
    if item in shopping_list:
        shopping_list.remove(item)

def show_items(shopping_list):
    for item in shopping_list:
        print(item)

def main():
    parser = argparse.ArgumentParser(description='CLI Shopping List')
    parser.add_argument('--file', type=str, default='shopping_list.json', help='Path to the saved JSON file')
    args = parser.parse_args()

    shopping_list = load_shopping_list(args.file)

    while True:
        command = input("Enter command (add ITEM, checked ITEM, show, or exit): ").strip().lower()
        if command == 'exit':
            save_shopping_list(args.file, shopping_list)
            break
        elif command.startswith('add '):
            item = command[4:].strip()
            add_item(shopping_list, item)
            print(f"Added: {item}")
        elif command.startswith('checked '):
            item = command[8:].strip()
            check_item(shopping_list, item)
            print(f"Checked: {item}")
        elif command == 'show':
            show_items(shopping_list)
        else:
            print("Invalid command. Please try again.")

if __name__ == '__main__':
    main()
