import curses
import time

def render(stdscr, hits, misses):
    stdscr.clear()
    stdscr.addstr(0, 0, f"Hits: {hits}")
    stdscr.addstr(1, 0, f"Misses: {misses}")
    stdscr.refresh()

def main(stdscr):
    curses.curs_set(0)
    stdscr.timeout(100)
    hits = 0
    misses = 0

    while True:
        render(stdscr, hits, misses)
        key = stdscr.getch()

        if key == ord('q'):
            break
        elif key == ord('r'):
            hits = 0
            misses = 0
        elif key == ord(' '):
            hits += 1
        elif key == ord('t'):
            misses += 1

if __name__ == "__main__":
    curses.wrapper(main)
